import java.io.*;
import java.util.Scanner;
public class JInputStat1 {
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil ism al-malaf:");
		String name = scan.next();
		JInputStat1 i1 = new JInputStat1();
		i1.getStat(name);
	}
	//Khutwa 1: Ta'reef al-tariqa
	public void getStat(String file_name) {
		//Khutwa 1.1: Ta'reef al-mutaghayyirat allati nahtajuha li-taqrir maelumat al-malaf
		int numLines = 0;
		String longestLine = "";
		//Khutwa 1.2: Ihit al-kod alladhi qad yulqi istithna dakhel blok try
		try {
			//Khutwa 1.2.1: Laff BufferedReader hawla FileReader
			FileReader fr = new FileReader(file_name); 
			BufferedReader br = new BufferedReader(fr); 
			//Khutwa 1.2.2: Istakhdim kaen BufferedReader liqira'at satar wahid fi al-marrah
			String line = null;
			while ( ( line = br.readLine() ) != null) {
				numLines += 1;
				String[] tokens = line.split(" ");
				int numWords = tokens.length;
				//Tahdid iza kana al-satr huwa atwal satar hatta al-aan
				if (line.length() > longestLine.length()) {
					longestLine = line;
				}
				//Taba'a maelumat al-satr
				System.out.println("Satr " + numLines + " fih " + numWords + " kalimat ");
			}
			System.out.println("Atwal satr:" + longestLine);
			//Khutwa 1.2.3: Sakkir kaen BufferedReader al-murtabit bil-malaf
			br.close();
		}
		//Khutwa 1.3: Ta'amul ma'a jami' al-istethna'at al-mumkin an tuthra fi blok try 
		catch (FileNotFoundException ex) {
			System.out.println("Malaf lam yujad");
		} catch (IOException ex ) {
			System.out.println("Mushkila fi al-malaf!");
		}
	}
}
